723	func inspectNetwork(e *PageEntry, p map[string]any) (any, error) {
724		events := e.NetworkSnapshot()
725		healthy, lastPush := e.NetworkHealth()
726		methods := stringSetFromParam(p["method"])
727		statusMin, hasMin := pNum(p, "status_min")
728		statusMax, hasMax := pNum(p, "status_max")
729		urlContains, _ := pStr(p, "url_contains")
730		filtered := make([]NetworkEvent, 0, len(events))
731		for _, ev := range events {
732			if ev.Phase != "response" && ev.Phase != "blocked" {
733				continue // 暴露响应事件和被拦截的 blocked 事件
734			}
735			if len(methods) > 0 {
736				if _, ok := methods[strings.ToUpper(ev.Method)]; !ok {
737					continue
738				}
739			}
740			if urlContains != "" && !strings.Contains(ev.URL, urlContains) {
741				continue
742			}
743			if hasMin && ev.Status < int64(statusMin) {
744				continue
745			}
746			if hasMax && ev.Status > int64(statusMax) {
747				continue
748			}
749			filtered = append(filtered, ev)
750		}
751		out := filterAndLimitEvents(filtered, p, func(ev NetworkEvent) map[string]any {
752			return map[string]any{
753				"timestamp":   ev.Timestamp.Format(time.RFC3339Nano),
754				"request_id":  ev.RequestID,
755				"method":      ev.Method,
756				"url":         ev.URL,
757				"status":      ev.Status,
758				"status_text": ev.StatusText,
759				"mime_type":   ev.MimeType,
760			}
761		})
762		return map[string]any{
763			"events":              out,
764			"count":               len(out),
765			"collection_healthy":  healthy,
766			"last_event_at":       lastPush.Format(time.RFC3339),
767		}, nil
768	}
