#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""自动化测试驱动: 通过 go-web-debug-tool 驱动 Chrome 测试 /VCTeamWeekly/auto_chat"""
import json, time, sys, os, requests

WDT = "http://localhost:28999"
PAGE_URL = "http://localhost:8082/VCTeamWeekly/auto_chat"
OUT = "/tmp/agent_test_round7"
os.makedirs(OUT, exist_ok=True)

def wdt_post(path, payload, timeout=60):
    r = requests.post(WDT + path, json=payload, timeout=timeout)
    return r.json()

def eval_js(page_id, expr, timeout=30):
    resp = wdt_post("/ControlChromePage", {
        "page_id": page_id,
        "action": "eval_js",
        "params": {"expression": expr, "await_promise": False}
    }, timeout=timeout)
    if resp.get("code") != 0:
        return None, resp
    data = resp.get("data") or {}
    result = data.get("result")
    # chromedp 返回结构: result 可能是 {type, value} 或直接值
    if isinstance(result, dict) and "value" in result:
        return result["value"], resp
    return result, resp

HOOK_JS = r"""
(function(){
  if (window.__respHookInstalled) return 'already';
  window.__lastResponses = [];
  var origSend = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.send = function(body){
    this.addEventListener('readystatechange', function(){
      if (this.readyState === 4) {
        try { window.__lastResponses.push({status: this.status, body: this.responseText, ts: Date.now()}); } catch(e){}
      }
    });
    return origSend.apply(this, arguments);
  };
  window.__respHookInstalled = true;
  return 'installed';
})()
"""

STATE_JS = r"""
(function(){
  var btn = document.getElementById('chatBtnOK');
  return JSON.stringify({
    disabled: btn ? btn.disabled : null,
    btnText: btn ? btn.innerText : null,
    respCount: (window.__lastResponses||[]).length,
    msgCount: document.getElementById('chatHistory') ? document.getElementById('chatHistory').children.length : -1,
    sessionId: (typeof currentSessionId !== 'undefined') ? currentSessionId : null
  });
})()
"""

EXTRACT_JS = r"""
(function(){
  var r = window.__lastResponses || [];
  if (r.length === 0) return JSON.stringify({error: 'no responses'});
  var last = r[r.length - 1];
  try {
    var j = JSON.parse(last.body);
    var d = j.data || {};
    var di = d.debugInfo || null;
    var toolNames = [];
    if (di && di.toolCalls) { for (var i=0;i<di.toolCalls.length;i++) toolNames.push(di.toolCalls[i].name); }
    return JSON.stringify({
      httpStatus: last.status,
      code: j.code,
      cacheHit: !!d.cacheHit,
      modelUsed: d.modelUsed || null,
      sessionId: d.sessionId || null,
      responseLen: (d.response||'').length,
      response: d.response || '',
      reasoningLen: (d.reasoningContent||'').length,
      webSearchUsed: !!d.webSearchUsed,
      deepThinkingUsed: !!d.deepThinkingUsed,
      debug: di ? {
        hitCount: di.hitCount, totalMatched: di.totalMatched,
        kgRetrievalSkipped: !!di.kgRetrievalSkipped,
        retrievalStrategy: di.retrievalStrategy || null,
        parseFallback: !!di.parseFallback,
        isBusinessMetricQuery: !!di.isBusinessMetricQuery,
        queryIntent: di.queryIntent || null,
        targetEmployee: di.targetEmployee || null,
        timeRange: di.timeRange || null,
        matchedKeywords: di.matchedKeywords || null,
        filteredKeywords: di.filteredKeywords || null,
        toolCalls: toolNames,
        toolCallCount: toolNames.length,
        degraded: di.degraded || null
      } : null,
      // DOM 侧: 助手消息徽章与 debug 面板是否渲染
      dom: (function(){
        var h = document.getElementById('chatHistory');
        if (!h || h.children.length === 0) return null;
        var lastDiv = h.children[h.children.length-1];
        var txt = lastDiv.innerText || '';
        return {
          badgeKG: txt.indexOf('基于知识库回答') >= 0,
          badgeStat: txt.indexOf('统计问答') >= 0,
          badgeGeneric: txt.indexOf('通用知识回答') >= 0,
          hasDebugPanel: txt.indexOf('知识库检索详情') >= 0,
          hasToolCalls: txt.indexOf('工具调用过程') >= 0,
          hasSVG: lastDiv.querySelector('svg') !== null
        };
      })()
    });
  } catch(e) {
    return JSON.stringify({httpStatus: last.status, parseError: String(e), rawHead: (last.body||'').substring(0, 500)});
  }
})()
"""

def get_state(page_id):
    v, _ = eval_js(page_id, STATE_JS)
    if v is None:
        return None
    try:
        return json.loads(v)
    except Exception:
        return None

def ask(page_id, qid, round_name, question, timeout_s=360):
    """发送一个问题并等待回答完成, 保存原始响应"""
    st0 = get_state(page_id)
    prev_resp = st0["respCount"] if st0 else 0

    # 输入
    r = wdt_post("/ControlChromePage", {
        "page_id": page_id, "action": "input_text",
        "params": {"selector": "#userPrompt", "text": question, "clear": True, "use_js": "true", "stable_ms": 300}
    })
    if r.get("code") != 0:
        return {"qid": qid, "round": round_name, "question": question, "error": f"input_text failed: {r}"}

    t0 = time.time()
    r = wdt_post("/ControlChromePage", {
        "page_id": page_id, "action": "click",
        "params": {"selector": "#chatBtnOK", "timeout_ms": 5000}
    })
    if r.get("code") != 0:
        return {"qid": qid, "round": round_name, "question": question, "error": f"click failed: {r}"}

    # 轮询等待完成: 按钮恢复可用 且 响应数增加
    deadline = t0 + timeout_s
    done = False
    last_log = 0
    while time.time() < deadline:
        time.sleep(5)
        st = get_state(page_id)
        if st is None:
            continue
        if st["respCount"] > prev_resp and st["disabled"] is False:
            done = True
            break
        if time.time() - last_log > 30:
            last_log = time.time()
            print(f"  [{qid}/{round_name}] waiting... {int(time.time()-t0)}s btn={st['btnText']} respCount={st['respCount']}", flush=True)

    elapsed = round(time.time() - t0, 1)
    v, raw = eval_js(page_id, EXTRACT_JS, timeout=60)
    result = {"qid": qid, "round": round_name, "question": question,
              "elapsed_s": elapsed, "waitDone": done, "ts": time.strftime("%H:%M:%S")}
    if v:
        try:
            result.update(json.loads(v))
        except Exception:
            result["extractRaw"] = v
    else:
        result["extractError"] = raw
    fn = os.path.join(OUT, f"{qid}_{round_name}.json")
    with open(fn, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    print(f"[{qid}/{round_name}] done={done} {elapsed}s respLen={result.get('responseLen')} tools={result.get('debug',{}) and result['debug'].get('toolCalls')} cacheHit={result.get('cacheHit')}", flush=True)
    return result

def clear_session(page_id):
    eval_js(page_id, "document.getElementById('clearBtn').click(); 'cleared'")
    time.sleep(0.5)

def main():
    # 1. 打开页面
    r = wdt_post("/NewChromePage", {"url": PAGE_URL, "wait_until": "load"}, timeout=90)
    if r.get("code") != 0:
        print("NewChromePage failed:", r); sys.exit(1)
    page_id = r["data"]["page_id"]
    print("page_id:", page_id, flush=True)
    time.sleep(2)

    # 2. 安装响应钩子
    v, _ = eval_js(page_id, HOOK_JS)
    print("hook:", v, flush=True)
    st = get_state(page_id)
    print("initial state:", st, flush=True)
    if not st or st["disabled"] is None:
        print("page sanity check failed"); sys.exit(2)

    tests = json.load(open(os.path.join(OUT, "tests.json"), encoding="utf-8"))
    for t in tests:
        qid = t["qid"]
        rounds = t["rounds"]
        print(f"=== {qid} ===", flush=True)
        clear_session(page_id)
        for i, q in enumerate(rounds):
            ask(page_id, qid, f"r{i+1}", q, timeout_s=t.get("timeout_s", 360))
            time.sleep(2)

    # 3. 收尾截图
    wdt_post("/ControlChromePage", {"page_id": page_id, "action": "screenshot",
                                    "params": {"full_page": False, "format": "jpeg", "quality": 70}}, timeout=60)
    print("ALL DONE", flush=True)

if __name__ == "__main__":
    main()

