222	func (server *LSMInterServer) retrieveWeeklyKnowledgeFromKG(toolReq WeeklyToolCallRequest) ([]TWeeklyKnowledgeNode, error) {
223		var nodes []TWeeklyKnowledgeNode
224	
225		// 构建查询
226		table_name := server.dbmysqlProvider.getTableTypeName(&TWeeklyKnowledgeNode{})
227		tx := server.dbmysqlProvider.db.Table(table_name)
228	
229		hasCondition := false
230	
231		// 1. 如果有 EmployeeName，增加精确匹配或 LIKE
232		if toolReq.EmployeeName != "" {
233			tx = tx.Where("EmployeeName = ?", toolReq.EmployeeName)
234			hasCondition = true
235		} else if toolReq.TargetRole != "" {
236			// 岗位角色下推(本次新增): 先把角色解析为员工名单,再下推 EmployeeName IN (...)
237			// 这样"产品的同学"就不会被拿去 LIKE 匹配 Category/摘要文本了——
238			// Category 是"单篇周报内容分类"(90% 为空),把它当岗位会把
239			// 「内容被分类为产品的周报」与「岗位是产品的人」混为一谈。
240			if role, roleErr := parseRoleArg(toolReq.TargetRole); roleErr == nil {
241				// [06 方案 §S5] minScore 传 0: 角色是否成立已由 Held 双条件
242				// (绝对强度 + 强特征词覆盖率)把关。旧值 0.2 是份额阈值,会滤掉
243				// 真实兼任者 —— 白茂生 manager 份额仅 0.09 却有 61% 排期表强特征覆盖率,
244				// 问"管理者在做什么"时他会被整个漏掉。
245				profiles, resolveErr := resolveEmployeesByRole(context.Background(), role, 0)
246				if resolveErr != nil {
247					log.Printf("[WARN] retrieveWeeklyKnowledgeFromKG: 角色 %s 解析员工失败(降级为不按角色过滤): %v", role, resolveErr)
248				} else if len(profiles) > 0 {
249					names := make([]string, 0, len(profiles))
250					for _, p := range profiles {
251						names = append(names, p.Employee)
252					}
253					tx = tx.Where("EmployeeName IN ?", names)
254					hasCondition = true
255					log.Printf("retrieveWeeklyKnowledgeFromKG: 角色 %s 解析为 %d 名员工: %v", role, len(names), names)
256				} else {
257					log.Printf("[WARN] retrieveWeeklyKnowledgeFromKG: 角色 %s 未匹配到任何员工", role)
258				}
259			} else {
260				log.Printf("[WARN] retrieveWeeklyKnowledgeFromKG: 角色参数非法 %q: %v", toolReq.TargetRole, roleErr)
261			}
262		}
263	
264		// 2. 如果有精确时间范围（工具解析结果优先），直接使用
265		if toolReq.StartTime != nil && toolReq.EndTime != nil {
266			tx = tx.Where("ReportTime >= ? AND ReportTime <= ?", *toolReq.StartTime, *toolReq.EndTime)
267			hasCondition = true
268			log.Printf("retrieveWeeklyKnowledgeFromKG: using resolved time range %s ~ %s", toolReq.StartTime.Format("2006-01-02"), toolReq.EndTime.Format("2006-01-02"))
269		} else if toolReq.TimeRange != "" {
270			// 否则尝试解析 TimeRange 字符串
271			startTime, endTime, err := parseTimeRange(toolReq.TimeRange)
272			if err == nil {
273				tx = tx.Where("ReportTime >= ? AND ReportTime <= ?", startTime, endTime)
274				hasCondition = true
275			} else {
276				// 时间过滤失效必须显式告警: 此时查询退化为无时间约束,结果可能与用户意图不符
277				log.Printf("[WARN] retrieveWeeklyKnowledgeFromKG: 时间过滤已失效 TimeRange=%s (parseTimeRange failed: %v), 本次查询未按时间筛选", toolReq.TimeRange, err)
278			}
279		}
280	
281		// 3. 处理 CoreProjects：构建 OR 条件（同时匹配新字段 Projects 和旧字段 CoreProjects）
282		if len(toolReq.CoreProjects) > 0 {
283			projectConditions := make([]string, 0, len(toolReq.CoreProjects))
284			projectArgs := make([]interface{}, 0, len(toolReq.CoreProjects)*3)
285			for _, proj := range toolReq.CoreProjects {
286				if proj != "" {
287					projPattern := "%" + proj + "%"
288					// 同时匹配 Projects (JSON), CoreProjects (逗号分隔), Summary
289					projectConditions = append(projectConditions, "(Projects LIKE ? OR CoreProjects LIKE ? OR Summary LIKE ?)")
290					projectArgs = append(projectArgs, projPattern, projPattern, projPattern)
291				}
292			}
293			if len(projectConditions) > 0 {
294				tx = tx.Where("("+strings.Join(projectConditions, " OR ")+")", projectArgs...)
295				hasCondition = true
296			}
297		}
298	
299		// 4. 处理 Keywords：使用 OR 连接多个关键词的查询（同时匹配新字段和旧字段）
300		// v1.9.8: 提问对象类词(周报/次数/篇数…)在**所有路径**无条件过滤;
301		// 汇总报告泛词(总结/汇总/报告…)仍只在 IgnoreGenericKeywords 时过滤。
302		keywords := toolReq.Keywords
303		if toolReq.IgnoreGenericKeywords {
304			keywords = filterGenericSummaryKeywords(keywords)
305		} else {
306			keywords = filterQuestionObjectKeywords(keywords)
307		}
308		if len(keywords) > 0 {
309			keywordConditions := make([]string, 0, len(keywords))
310			keywordArgs := make([]interface{}, 0, len(keywords)*9)
311			for _, kw := range keywords {
312				if kw != "" {
313					kwPattern := "%" + kw + "%"
314					// 同时匹配所有相关字段（新旧字段兼容，含 Entities 和 Category）
315					keywordConditions = append(keywordConditions,
316						"(Keywords LIKE ? OR Summary LIKE ? OR CoreProjects LIKE ? OR Projects LIKE ? OR Technologies LIKE ? OR Issues LIKE ? OR Achievements LIKE ? OR Entities LIKE ? OR Category LIKE ?)")
317					keywordArgs = append(keywordArgs, kwPattern, kwPattern, kwPattern, kwPattern, kwPattern, kwPattern, kwPattern, kwPattern, kwPattern)
318				}
319			}
320			if len(keywordConditions) > 0 {
321				tx = tx.Where("("+strings.Join(keywordConditions, " OR ")+")", keywordArgs...)
322				hasCondition = true
323			}
324		}
325	
326		// 5. 如果有 SummaryFocus，在 Summary 中进行模糊匹配
327		if toolReq.SummaryFocus != "" && !toolReq.IgnoreGenericKeywords {
328			focusPattern := "%" + toolReq.SummaryFocus + "%"
329			tx = tx.Where("Summary LIKE ?", focusPattern)
330			hasCondition = true
331		}
332	
333		// 6. 执行查询，普通问答默认取最近记录；报告类可按时间升序扩大范围
334		limit := normalizeWeeklyRetrievalLimit(toolReq.MaxResults)
335		orderBy := "ReportTime DESC"
336		if toolReq.Chronological {
337			orderBy = "ReportTime ASC"
338		}
339	
340		// 截断可见化(本次新增): 先在相同条件下取总命中数,再 LIMIT 取回。
