func (server *LSMInterServer) findEmployeeNameInPrompt(prompt string) string {
	// roster: DB 真实员工花名册。正则兜底候选必须经本花名册校验,
	// 防止 "位的员工" / "一名员工" 等片段被误认为员工名 (v1.9.17: Q91 "团队里产品岗位的员工最近都在做什么" → "位的员工")
	var roster []string
	if server != nil && server.dbmysqlProvider != nil && server.dbmysqlProvider.db != nil {
		tableName := server.dbmysqlProvider.getTableTypeName(&TWeeklyKnowledgeNode{})
		if err := server.dbmysqlProvider.db.Table(tableName).Distinct("EmployeeName").Pluck("EmployeeName", &roster).Error; err == nil {
			for _, name := range roster {
				name = strings.TrimSpace(name)
				if name != "" && strings.Contains(prompt, name) {
					return name
				}
			}
		} else {
			log.Printf("findEmployeeNameInPrompt: query employee names failed: %v", err)
		}
	}

	re := regexp.MustCompile(`([\p{Han}]{2,4})(?:最近|近|过去|本年|今年)`) // 如：刘诗萌最近1年
	matches := re.FindStringSubmatch(prompt)
	if len(matches) == 2 {
		candidate := strings.TrimSpace(matches[1])
		for _, name := range roster {
			if name == candidate {
				return candidate
			}
		}
		// 不在花名册即拒绝: 宁可留空走后续角色/时间兜底, 不可把垃圾片段当员工名
